// Self-checking testbench for hop_lfsr_fold: (a) all 65535 non-zero states -> one hop each vs sn % 13 computed in the bench,
// (b) 4 seeds x 20000 hops vs the Python LFSR vectors (vec_lfsr.mem, generated by model/gen_vectors.py). FV selected by -DFV.
`timescale 1ns/1ps
module tb_hop_lfsr_fold;
    reg clk = 0, rst_n = 0; reg [15:0] seed_in; reg seed_we = 0, req = 0;
    wire valid; wire [3:0] chan;
    hop_lfsr_fold #(.FV(`FV)) dut (.clk(clk), .rst_n(rst_n), .seed_in(seed_in), .seed_we(seed_we), .req(req), .valid(valid), .chan(chan));
    always #5 clk = ~clk;
    reg [7:0] vec [0:79999]; reg [15:0] seeds [0:3];
    integer k, i, errs, errs_ex, cyc, cmax; reg [15:0] sn, sv; reg fbv;
    initial begin
        $readmemh({`VDIR, "vec_lfsr.mem"}, vec); $readmemh({`VDIR, "seeds_lfsr.mem"}, seeds);
        errs = 0; errs_ex = 0; cmax = 0;
        repeat (3) @(posedge clk); rst_n = 1; repeat (2) @(posedge clk);
        for (k = 1; k < 65536; k = k + 1) begin               // exhaustive: load state k, take one hop
            sv = k; fbv = sv[0] ^ sv[2] ^ sv[3] ^ sv[5]; sn = {fbv, sv[15:1]};
            @(negedge clk); seed_in = sv; seed_we = 1; @(negedge clk); seed_we = 0; req = 1; @(negedge clk); req = 0;
            if (!valid || chan !== (sn % 16'd13)) begin errs_ex = errs_ex + 1; if (errs_ex < 10) $display("EXH MISMATCH state=%h rtl=%0d exp=%0d", sv, chan, sn % 16'd13); end
        end
        for (k = 0; k < 4; k = k + 1) begin
            @(negedge clk); seed_in = seeds[k]; seed_we = 1; @(negedge clk); seed_we = 0;
            for (i = 0; i < 20000; i = i + 1) begin
                req = 1; cyc = 0; @(negedge clk); req = 0;
                while (!valid) begin @(negedge clk); cyc = cyc + 1; end
                cyc = cyc + 1; if (cyc > cmax) cmax = cyc;
                if (chan !== vec[k*20000 + i][3:0]) begin errs = errs + 1; if (errs < 10) $display("MISMATCH k=%0d i=%0d rtl=%0d exp=%0d", k, i, chan, vec[k*20000+i]); end
            end
        end
        $display("TB[lfsr_fold FV=%0d] exhaustive states=65535 errs=%0d ; python-vector hops=80000 errs=%0d ; max cycles req->valid=%0d", `FV, errs_ex, errs, cmax);
        if (errs == 0 && errs_ex == 0) $display("RESULT lfsr_fold_FV%0d PASS", `FV); else $display("RESULT lfsr_fold_FV%0d FAIL", `FV);
        $finish;
    end
endmodule
